#!/usr/bin/env python3
"""Build a self-contained offline asset browser from the actual profile files."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]

def collect():
    data=[]
    for family in ['characters','pets','codexmini']:
        for p in sorted((ROOT/family).glob('*/profile.json')):
            obj=json.loads(p.read_text());folder=p.parent;relative=folder.relative_to(ROOT).as_posix()
            group='animals' if family=='pets' else ('mini' if family=='codexmini' else ('original' if int(folder.name.split('_')[0])<=20 else 'new'))
            manifest=folder/'animation.json';ani=json.loads(manifest.read_text()) if manifest.exists() else {}
            portrait=next((name for name in ['portrait.png','frame_01.png','idle.png'] if (folder/name).exists()),None)
            actions=[]
            for key,value in ani.get('animations',{}).items():
                gif=value.get('gif');exists=bool(gif and (folder/gif).exists())
                actions.append({'id':key,**value,'gif':f'{relative}/{gif}' if exists else None,'atlas':f"{relative}/{value['atlas']}" if value.get('atlas') and (folder/value['atlas']).exists() else None})
            overview=next((str(folder/name).replace(str(ROOT)+'/','') for name in ['overview.gif','all_actions.gif'] if (folder/name).exists()),None)
            data.append({'profile':obj,'id':obj.get('id',folder.name),'group':group,'folder':relative,'portrait':f'{relative}/{portrait}' if portrait else None,'actions':actions,'overview':overview,'profileMd':f'{relative}/profile.md','animationJson':f'{relative}/animation.json' if manifest.exists() else None,'missingActions':ani.get('missingActions',[])})
    return data

